    "function mon2ApplyCore(roots){MON2_STATE.source={mode:'cloud',monitorDatabase:'reachable',lastCloudRefreshAt:Date.now(),lastCloudError:'',lastCloudStatus:200};MON2_STATE.runtime=roots.runtime||{};MON2_STATE.events=mon2FlattenEvents(roots.events||{});MON2_STATE.events.sort(mon2EventSort);MON2_STATE.issues=mon2AggregateIssues(MON2_STATE.events);mon2ApplyIssueStates(roots.issues||{});}",
