    "function mon2ApplyRefresh(roots){mon2ApplyCore(roots);mon2ApplyDerived(roots);mon2Render();mon2Banner('');}",
    "function mon2SetSourceFailed(code,identity){const previous=MON2_STATE.source||{};const status=code.indexOf('HTTP_')===0?(Number(code.substring(5))||0):0;MON2_STATE.source={mode:'local',monitorDatabase:identity?'auth_denied':(code==='MONITOR_TOKEN_MISSING'?'unavailable':'network_error'),lastCloudRefreshAt:Number(previous.lastCloudRefreshAt)||0,lastCloudError:code,lastCloudStatus:status};}",
    "function mon2RefreshFailed(error){const code=error.message||'';const identity=(code==='HTTP_401'||code==='HTTP_403');mon2SetSourceFailed(code,identity);mon2LoadLocal();const banner=document.getElementById('mon2Banner');if(banner)banner.setAttribute('data-tone',identity?'bad':'warn');mon2Banner(identity?'هوية الرصد غير معتمدة أو انتهت صلاحيتها — تعذّرت القراءة من المصدر السحابي':'تعذر المصدر السحابي؛ عُرضت البيانات المحلية');}",
    "async function mon2Refresh(){if(MON2_BUSY)return;MON2_BUSY=true;mon2Banner('جارٍ تحديث حالة الرصد…');try{const today=new Date().toISOString().slice(0,10),runtime=await mon2FetchJsonQuery('runtime','$key',200),eventsRoot=await mon2FetchEventsSnapshot(today,runtime||{}),issuesRoot=await mon2FetchJsonQuery('issues','updatedAt',500),journeysRoot=await mon2FetchJourneysSnapshot(today,runtime||{}),enrollmentsRoot=await mon2FetchJsonQuery('enrollment_requests','requestedAt',200),identitiesRoot=await mon2FetchJsonQuery('identities','$key',500);mon2ApplyRefresh({runtime:runtime,events:eventsRoot,issues:issuesRoot,journeys:journeysRoot,enrollments:enrollmentsRoot,identities:identitiesRoot});}catch(error){mon2RefreshFailed(error);}finally{MON2_BUSY=false;}}",
    "function mon2ApplyIssueStates(root){for(let i=0;i<MON2_STATE.issues.length;i++){const saved=root[MON2_STATE.issues[i].fingerprint];if(saved&&saved.state)MON2_STATE.issues[i].state=saved.state;}}",
    "function mon2LoadLocal(){const rows=Array.isArray(MON2_BOOT.localRows)?MON2_BOOT.localRows:[];MON2_STATE.events=rows.slice().sort(mon2EventSort);MON2_STATE.issues=mon2AggregateIssues(MON2_STATE.events);MON2_STATE.employees=[];MON2_STATE.journeys=MON2_BOOT.localAuthJourneys||[];MON2_STATE.metrics=mon2Metrics(MON2_STATE.events,[]);mon2AppendTelemetryIssue();MON2_STATE.system=mon2SystemState(MON2_STATE.issues,[],MON2_STATE.metrics);mon2Render();}",
    "function mon2DetailRow(label,value,direction){const row=mon2Node('div',undefined,'mon2-detail-row');row.appendChild(mon2Node('b',label));const empty=value===null||value===undefined||value==='';const span=mon2Node('span',empty?'—':value);if(direction==='ltr')span.setAttribute('dir','ltr');row.appendChild(span);return row;}",
    "function mon2FindBy(list,key,value){let found=null;for(let i=0;i<list.length;i++)if(list[i][key]===value)found=list[i];return found;}",
    "function mon2ModalOpen(title){const modal=document.getElementById('mon2Modal');const body=document.getElementById('mon2ModalBody');const actions=document.getElementById('mon2ModalActions');mon2Clear(body);mon2Clear(actions);document.getElementById('mon2ModalTitle').textContent=title;return {modal:modal,body:body,actions:actions};}",
    "function mon2IssueRowsA(body,issue){body.appendChild(mon2DetailRow('البصمة',issue.fingerprint));body.appendChild(mon2DetailRow('النطاق',issue.scope));body.appendChild(mon2DetailRow('سبب التصنيف',issue.affectedUsers>=3?'ظهرت عند ثلاثة موظفين أو أكثر':'محصورة في موظف واحد أو عينة غير كافية'));body.appendChild(mon2DetailRow('الملف',issue.code.fileName));body.appendChild(mon2DetailRow('الدالة',issue.code.functionName));}",
    "function mon2IssueRowsB(body,issue){body.appendChild(mon2DetailRow('السطر والعمود',(issue.code.line||0)+':'+(issue.code.column||0)));body.appendChild(mon2DetailRow('التكرار',issue.count));body.appendChild(mon2DetailRow('الموظفون المتأثرون',issue.affectedUsers));const latest=issue.events[0]||{};body.appendChild(mon2Node('pre',latest.exception&&latest.exception.stacktrace||'لا يوجد مكدس','mon2-stack'));}",
